mapper.select:
/* CastDsbdMapper.retrieveSmltIdByYmd */
SELECT MAX(A.SMLT_ID) AS SMLT_ID
FROM PMOWN.TN_PM_SMLT_STNG A
WHERE 1 = 1
AND A.EXCN_YMD = #{ymd}
AND A.SMLT_TYPE = #{smltType}

/* CastDsbdMapper.retrieveLastCalcDt */
SELECT NVL(TO_CHAR(MAX(A.SMLT_EXCN_DT), 'YYYYMMDDHH24MISS'), '') AS LAST_CALC_DT
FROM PMOWN.TN_PM_SMLT_RSLT_DTL A
WHERE 1 = 1
AND A.SMLT_ID = #{smltId}

/* CastDsbdMapper.retrieveAvlTimeList */
SELECT DISTINCT TO_CHAR(A.SMLT_ACTL_DT, 'HH24MI') AS AVL_TIME
FROM PMOWN.TN_PM_SMLT_RSLT_DTL A
WHERE 1 = 1
AND A.SMLT_ID = #{smltId}
ORDER BY AVL_TIME

/* CastDsbdMapper.retrieveFltSmryByTime */
SELECT 
FROM GOOWN.TN_GO_GD_DATA A
WHERE 1 = 1
AND A.GD_SE_YMD = #{ymd}
AND A.TMNL_ID IN (#{item})
-- 예측시분은 날짜 없는 HHmm 문자열이라 사전순 비교로 구간을 자른다.
-- 자정을 넘는 구간은 호출하는 쪽이 끝을 '2400' 으로 잘라 넘긴다
AND A.PREDC_HM >= #{bgnHhmm}
AND A.PREDC_HM < #{endHhmm}

/* CastDsbdMapper.retrieveHourlyFltPsgList */ SELECT SUBSTR(A.PREDC_HM, 1, 2) AS HOUR, COUNT(*) AS FLT_CNT, NVL(SUM(A.RSVT_BDPSG_CNT - A.RSVT_TRNS_BDPSG_CNT), 0) AS PSG_CNT FROM GOOWN.TN_GO_GD_DATA A WHERE 1 = 1 AND A.GD_SE_YMD = #{ymd} AND A.ARR_DEP_SE_CD = 'D'
AND A.TMNL_ID IN (#{item})
AND A.PREDC_HM IS NOT NULL GROUP BY SUBSTR(A.PREDC_HM, 1, 2) ORDER BY HOUR

/* CastDsbdMapper.retrieveHourlyBdpsgAnceList */ -- 승객예고는 10분 간격이다. 화면 축이 1시간이라 시 단위로 합산한다 -- BDPSG_ANCE_SE_CD='DE' 는 출발 탑승객예고다 (도착은 화면에서 아직 안 쓴다) SELECT A.BDPSG_ANCE_HOUR AS HOUR, NVL(SUM(A.EST_BRDG_TNOPE), 0) AS EST_BRDG_TNOPE FROM PMOWN.TN_PM_BDPSG_ANCE_RSLT A WHERE 1 = 1 AND A.BDPSG_ANCE_SE_CD = 'DE' AND A.BDPSG_ANCE_YMD = #{ymd}
AND A.TMNL_ID IN (#{item})
GROUP BY A.BDPSG_ANCE_HOUR ORDER BY HOUR

/* CastDsbdMapper.retrieveHourlyPsgDptcnyTrnsPrfmncList */ SELECT TO_CHAR(A.TOT_DT, 'HH24') AS HOUR, NVL(SUM(A.BDPSG_PRCS_CNT), 0) AS PRCS_PSG_CNT FROM PMOWN.TN_PM_PSG_DPTCNY_TRNS_PRFMNC A WHERE 1 = 1 AND TO_CHAR(A.TOT_DT, 'YYYYMMDD') = #{ymd}
AND A.TMNL_ID IN (#{item})
-- 이 테이블은 구코드(T1LG3 등)로 넣는 다른 프로세스와 같이 쓴다. -- 같은 출국장이 신/구 코드로 중복 집계되지 않도록 신코드(D1~D6) 행만 센다 AND REGEXP_LIKE(A.PSG_FCLT_CD, '^D[1-6]$') GROUP BY TO_CHAR(A.TOT_DT, 'HH24') ORDER BY HOUR

/* CastDsbdMapper.retrievePsgWtngByHourList */ -- 여객대기정보(Xovis 실측)도 10분 간격이다. 접는 방식은 retrieveRsltByHourList 와 맞춘다 -- (예측선과 실적선을 같은 축에 겹쳐 그리므로 대기인원은 합이 아니라 MAX 로 통일한다) SELECT SUBSTR(A.PSG_FLOW_DATA_CRT_DT, 9, 2) || '00' AS TIME, NVL(MAX(A.WTNG_LINE_LEN), 0) AS WTNG_PSG_CNT FROM PMOWN.TN_PM_PSG_WTNG_INFO A WHERE 1 = 1 -- 여객흐름자료생성일시는 yyyyMMddHHmm 문자열이자 PK 선두라 앞자리 범위로 자른다 AND A.PSG_FLOW_DATA_CRT_DT BETWEEN #{ymd} || '0000' AND #{ymd} || '2359' AND A.TMNL_ID = #{tmnlId}
-- Queue 체크인 대기열, DG 출국장, SC 보안검색대 AND A.FCLT_TYPE_CD IN (#{item})
GROUP BY SUBSTR(A.PSG_FLOW_DATA_CRT_DT, 9, 2) ORDER BY TIME

/* CastDsbdMapper.retrieveRsltByUnitList */
SELECT 
FROM PMOWN.TN_PM_SMLT_RSLT_DTL A
    INNER JOIN PMOWN.TN_PM_SMLT_PSG_FCLT B
    ON A.PSG_FCLT_CD = B.PSG_FCLT_CD
WHERE 1 = 1
AND A.SMLT_ID = #{smltId}
AND B.TMNL_ID = #{tmnlId}
AND B.USE_YN = 'Y'
AND B.UP_PSG_FCLT_CD IN (#{item})
AND A.SMLT_ACTL_DT >= #{bgnDt}
AND A.SMLT_ACTL_DT < #{endDt}
GROUP BY A.SMLT_ACTL_DT, B.UP_PSG_FCLT_CD, 
ORDER BY A.SMLT_ACTL_DT, B.UP_PSG_FCLT_CD, UNIT_CD

/* CastDsbdMapper.retrieveRsltAtTimeList */
SELECT 
FROM PMOWN.TN_PM_SMLT_RSLT_DTL A
    INNER JOIN PMOWN.TN_PM_SMLT_PSG_FCLT B
    ON A.PSG_FCLT_CD = B.PSG_FCLT_CD
WHERE 1 = 1
AND A.SMLT_ID = #{smltId}
AND B.TMNL_ID = #{tmnlId}
AND B.USE_YN = 'Y'
AND B.UP_PSG_FCLT_CD IN (#{item})
AND A.SMLT_ACTL_DT = #{smltActlDt}
GROUP BY A.SMLT_ACTL_DT, B.UP_PSG_FCLT_CD, 
ORDER BY B.UP_PSG_FCLT_CD, UNIT_CD

/* CastDsbdMapper.retrieveChknAlnAssignmentList */
WITH VALID_ASSIGNMENT AS ( SELECT X.CKNCT_ID, X.ALN_CD FROM ( SELECT A.CKNCT_ID, A.ALN_CD, TO_DATE( A.OPER_YMD || CASE WHEN A.LAST_BGNG_HM IS NOT NULL AND A.LAST_END_HM IS NOT NULL THEN A.LAST_BGNG_HM ELSE A.EST_BGNG_HM END, 'YYYYMMDDHH24MI' ) AS BGN_DT, TO_DATE( CASE WHEN CASE WHEN A.LAST_BGNG_HM IS NOT NULL AND A.LAST_END_HM IS NOT NULL THEN A.LAST_RON_YN ELSE A.EST_RON_YN END = 'Y' THEN TO_CHAR(TO_DATE(A.OPER_YMD, 'YYYYMMDD') + 1, 'YYYYMMDD') ELSE A.OPER_YMD END || CASE WHEN A.LAST_BGNG_HM IS NOT NULL AND A.LAST_END_HM IS NOT NULL THEN A.LAST_END_HM ELSE A.EST_END_HM END, 'YYYYMMDDHH24MI' ) AS END_DT FROM GOOWN.TI_GO_CKNCT_DALY_ALOT A INNER JOIN CAOWN.TN_CA_CKNCT B ON A.CKNCT_ID = B.CKNCT_ID AND A.TMNL_ID = B.TMNL_ID WHERE A.USE_YN = 'Y' AND B.USE_YN = 'Y' AND B.CKNCT_USE_CRG_APLCN_TYPE_CD IN ('A', 'B') AND A.TMNL_ID = #{tmnlId} AND A.OPER_YMD BETWEEN TO_CHAR(TO_DATE(#{excnYmd}, 'YYYYMMDD') - 1, 'YYYYMMDD') AND #{excnYmd} AND A.CKNCT_ID NOT LIKE 'X%' AND A.CKNCT_ID NOT LIKE 'Y%' AND A.CKNCT_ID NOT LIKE 'R%' AND A.CKNCT_ID NOT LIKE 'S%' AND CASE WHEN A.LAST_BGNG_HM IS NOT NULL AND A.LAST_END_HM IS NOT NULL THEN A.LAST_BGNG_HM ELSE A.EST_BGNG_HM END IS NOT NULL AND CASE WHEN A.LAST_BGNG_HM IS NOT NULL AND A.LAST_END_HM IS NOT NULL THEN A.LAST_END_HM ELSE A.EST_END_HM END IS NOT NULL ) X WHERE X.BGN_DT <= #{bgnDt} AND X.END_DT > #{bgnDt} ) SELECT SUBSTR(V.CKNCT_ID, 1, 1) AS UNIT_CD, V.ALN_CD, N.ALN_NM, COUNT(DISTINCT V.CKNCT_ID) AS ASSIGNED_CNT, O.OPEN_CNT FROM VALID_ASSIGNMENT V INNER JOIN ( SELECT SUBSTR(CKNCT_ID, 1, 1) AS UNIT_CD, COUNT(DISTINCT CKNCT_ID) AS OPEN_CNT FROM VALID_ASSIGNMENT GROUP BY SUBSTR(CKNCT_ID, 1, 1) ) O ON SUBSTR(V.CKNCT_ID, 1, 1) = O.UNIT_CD LEFT JOIN ( SELECT ALN_CD, MAX(ALN_NM) AS ALN_NM FROM CAOWN.TN_CA_ALN GROUP BY ALN_CD ) N ON V.ALN_CD = N.ALN_CD GROUP BY SUBSTR(V.CKNCT_ID, 1, 1), V.ALN_CD, N.ALN_NM, O.OPEN_CNT ORDER BY UNIT_CD, ASSIGNED_CNT DESC, V.ALN_CD
WITH VALID_ASSIGNMENT AS ( SELECT A.CKNCT_ID, A.ALN_CD FROM PMOWN.TN_PM_SMLT_CKNCT_ATRB A WHERE A.SCHDL_ATRB_GROUP_ID = REGEXP_REPLACE(#{cknctAlctnRsrcId}, '^CA', '') AND A.TMNL_ID = #{tmnlId} AND A.CHKN_OPEN_PRNMNT_DT IS NOT NULL AND A.CHKN_CLOSE_PRNMNT_DT IS NOT NULL AND TO_DATE(A.CHKN_OPEN_PRNMNT_DT, 'YYYYMMDDHH24MI') <= #{bgnDt} AND TO_DATE(A.CHKN_CLOSE_PRNMNT_DT, 'YYYYMMDDHH24MI') > #{bgnDt} ) SELECT SUBSTR(V.CKNCT_ID, 1, 1) AS UNIT_CD, V.ALN_CD, N.ALN_NM, COUNT(DISTINCT V.CKNCT_ID) AS ASSIGNED_CNT, O.OPEN_CNT FROM VALID_ASSIGNMENT V INNER JOIN ( SELECT SUBSTR(CKNCT_ID, 1, 1) AS UNIT_CD, COUNT(DISTINCT CKNCT_ID) AS OPEN_CNT FROM VALID_ASSIGNMENT GROUP BY SUBSTR(CKNCT_ID, 1, 1) ) O ON SUBSTR(V.CKNCT_ID, 1, 1) = O.UNIT_CD LEFT JOIN ( SELECT ALN_CD, MAX(ALN_NM) AS ALN_NM FROM CAOWN.TN_CA_ALN GROUP BY ALN_CD ) N ON V.ALN_CD = N.ALN_CD GROUP BY SUBSTR(V.CKNCT_ID, 1, 1), V.ALN_CD, N.ALN_NM, O.OPEN_CNT ORDER BY UNIT_CD, ASSIGNED_CNT DESC, V.ALN_CD
